import{_ as d,C as s,o as a,c as r,a7 as e,b as h,w as i,a as o,E as l,a8 as p}from"./chunks/framework.BCbKzsgW.js";const m=JSON.parse('{"title":"预约服务：改期、批量提醒与迟到处理","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"development/common/task-scheduling/scenarios/appointments.md","filePath":"development/common/task-scheduling/scenarios/appointments.md","lastUpdated":1793441194000}'),E={name:"development/common/task-scheduling/scenarios/appointments.md"};function u(c,t,g,A,k,b){const n=s("Mermaid");return a(),r("div",null,[t[1]||(t[1]=e('<h1 id="yu-yue-fu-wugai-qipi-liang-ti-xing-yu-chi-dao-chu-li" tabindex="-1">预约服务：改期、批量提醒与迟到处理 <a class="header-anchor" href="#yu-yue-fu-wugai-qipi-liang-ti-xing-yu-chi-dao-chu-li" aria-label="Permalink to &quot;预约服务：改期、批量提醒与迟到处理&quot;">​</a></h1><p>预约提醒由预约的开始时间产生，不依赖参与者登录。登录时展示的是当前日程；后台提醒则覆盖用户不在线时的触达。</p><p>示例规则是“预约确认后，在开始前 24 小时和 30 分钟提醒，取消后停止发送”。如果预约创建时距开始只剩 20 分钟，可以只发送确认消息，不再补齐已经错过的两档提醒。</p><h2 id="cong-yi-tiao-ti-xing-xu-qiu-tui-dao-yu-yue-mo-xing" tabindex="-1">从一条提醒需求推导预约模型 <a class="header-anchor" href="#cong-yi-tiao-ti-xing-xu-qiu-tui-dao-yu-yue-mo-xing" aria-label="Permalink to &quot;从一条提醒需求推导预约模型&quot;">​</a></h2><p>以会议室预约为例：用户约好周五 10:00 的场次，希望提前收到提醒。只保存手机号与发送时间，可以完成一次发送；但会议改到 11:00 后，系统还需要知道这条提醒属于哪个场次的哪个版本。</p><table tabindex="0"><thead><tr><th>候选方案</th><th>能解决什么</th><th>需要补充的约束</th></tr></thead><tbody><tr><td>按手机号和时间保存发送任务</td><td>一次性人工通知</td><td>无法自然关联改期、取消和参与人变化</td></tr><tr><td>定期扫描近期预约</td><td>发现当前有效日程</td><td>提醒阶段去重、窗口补扫和参与人展开</td></tr><tr><td>确认或改期时保存提醒计划</td><td>追踪每轮日程变化</td><td>旧任务识别、成员变化和任务恢复</td></tr></tbody></table><p>本篇用“场次名额、预约记录、参与人关系、提醒计划”分别保存事实。占位是否成功属于预约事务；提醒是否发送属于通知流程。把它们分开，才能在短信服务故障时保留有效预约。</p><h2 id="gai-qi-yu-ti-xing-de-zhi-xing-shi-xu" tabindex="-1">改期与提醒的执行时序 <a class="header-anchor" href="#gai-qi-yu-ti-xing-de-zhi-xing-shi-xu" aria-label="Permalink to &quot;改期与提醒的执行时序&quot;">​</a></h2><p>改期先作为一个原子业务操作提交，提醒展开和渠道发送随后处理。这里只画“新场次可用”的成功改期，名额不足时整个改期回滚。</p>',9)),(a(),h(p,null,{default:i(()=>[l(n,{id:"mermaid-74",class:"mermaid",graph:"sequenceDiagram%0A%20%20%20%20actor%20U%20as%20%E9%A2%84%E7%BA%A6%E4%BA%BA%0A%20%20%20%20participant%20A%20as%20%E9%A2%84%E7%BA%A6%E6%8E%A5%E5%8F%A3%0A%20%20%20%20participant%20D%20as%20%E6%95%B0%E6%8D%AE%E5%BA%93%0A%20%20%20%20participant%20W%20as%20%E6%8F%90%E9%86%92%20Worker%0A%20%20%20%20participant%20C%20as%20%E9%80%9A%E7%9F%A5%E6%B8%A0%E9%81%93%0A%20%20%20%20U-%3E%3EA%3A%20%E6%94%B9%E6%9C%9F%E5%B9%B6%E6%8F%90%E4%BA%A4%E9%A2%84%E6%9C%9F%E7%89%88%E6%9C%AC%0A%20%20%20%20A-%3E%3ED%3A%20%E5%90%8C%E4%BA%8B%E5%8A%A1%E5%8D%A0%E6%96%B0%E5%90%8D%E9%A2%9D%E3%80%81%E9%87%8A%E6%94%BE%E6%97%A7%E5%90%8D%E9%A2%9D%3Cbr%3E%E6%8E%A8%E8%BF%9B%E7%89%88%E6%9C%AC%E5%B9%B6%E4%BF%9D%E5%AD%98%E6%8F%90%E9%86%92%E8%AE%A1%E5%88%92%0A%20%20%20%20D--%3E%3EA%3A%20%E6%8F%90%E4%BA%A4%E6%96%B0%E7%89%88%E6%9C%AC%0A%20%20%20%20A--%3E%3EU%3A%20%E8%BF%94%E5%9B%9E%E6%9C%80%E6%96%B0%E9%A2%84%E7%BA%A6%0A%20%20%20%20W-%3E%3ED%3A%20%E9%A2%86%E5%8F%96%E5%88%B0%E6%97%B6%E8%AE%A1%E5%88%92%3Cbr%3E%E6%A0%B8%E5%AF%B9%E9%A2%84%E7%BA%A6%E4%B8%8E%E6%88%90%E5%91%98%E7%89%88%E6%9C%AC%0A%20%20%20%20alt%20%E4%BB%8D%E6%98%AF%E5%BD%93%E5%89%8D%E6%9C%89%E6%95%88%E8%AE%A1%E5%88%92%0A%20%20%20%20%20%20%20%20loop%20%E5%88%86%E6%89%B9%E5%B1%95%E5%BC%80%E6%9C%89%E6%95%88%E6%88%90%E5%91%98%0A%20%20%20%20%20%20%20%20%20%20%20%20W-%3E%3ED%3A%20%E4%BF%9D%E5%AD%98%E9%80%9A%E7%9F%A5%E6%84%8F%E5%9B%BE%3Cbr%3E%E4%B8%8E%E6%9C%AC%E6%89%B9%E6%A3%80%E6%9F%A5%E7%82%B9%0A%20%20%20%20%20%20%20%20end%0A%20%20%20%20%20%20%20%20W-%3E%3ED%3A%20%E5%8F%91%E9%80%81%E5%89%8D%E5%86%8D%E6%AC%A1%E6%A0%B8%E5%AF%B9%E7%8A%B6%E6%80%81%0A%20%20%20%20%20%20%20%20W-%3E%3EC%3A%20%E9%99%90%E9%80%9F%E6%8F%90%E4%BA%A4%E4%BB%8D%E6%9C%89%E6%95%88%E7%9A%84%E6%8F%90%E9%86%92%0A%20%20%20%20%20%20%20%20C--%3E%3EW%3A%20%E8%BF%94%E5%9B%9E%E6%B8%A0%E9%81%93%E7%BB%93%E6%9E%9C%0A%20%20%20%20%20%20%20%20W-%3E%3ED%3A%20%E4%BF%9D%E5%AD%98%E7%BB%93%E6%9E%9C%E6%88%96%E9%87%8D%E8%AF%95%0A%20%20%20%20else%20%E6%97%A7%E7%89%88%E6%9C%AC%E3%80%81%E5%8F%96%E6%B6%88%E6%88%96%E8%BF%87%E6%97%B6%0A%20%20%20%20%20%20%20%20W-%3E%3ED%3A%20%E8%AE%B0%E5%BD%95%20skipped%0A%20%20%20%20end%0A"})]),fallback:i(()=>[...t[0]||(t[0]=[o(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=e(`<p>展开任务与渠道发送可以由不同 Worker 承担，图中合并为一个角色以突出顺序。成员独立的通知结果使一人失败不会触发整场重复发送。</p><h2 id="yu-yue-xu-qiu-yu-yan-shou-yue-shu" tabindex="-1">预约需求与验收约束 <a class="header-anchor" href="#yu-yue-xu-qiu-yu-yan-shou-yue-shu" aria-label="Permalink to &quot;预约需求与验收约束&quot;">​</a></h2><p>提醒之前还要保证预约本身有效。示例采用固定场次与名额模型：同一请求不能重复占位，确认成功才安排提醒，改期必须成功占到新场次后才能释放旧名额。</p><p>这里一次会议预约占一个资源名额，可以关联多个通知参与人。若课程按实际人数占座，则应按席位数量扣减并保存对应占位关系，不能把下面的减 1 原样用于团体订课。</p><table tabindex="0"><thead><tr><th>业务问题</th><th>示例决策</th><th>实现约束</th></tr></thead><tbody><tr><td>一个场次是否允许多人预约</td><td>允许，最多为场次配置的容量</td><td>名额扣减与预约确认同事务</td></tr><tr><td>预约是否可修改</td><td>开始前可改，是否收费另行定义</td><td>接口携带预期版本</td></tr><tr><td>新参与人加入时是否补提醒</td><td>只补仍有价值的阶段</td><td>按参与人创建独立意图</td></tr><tr><td>通知多久算迟到</td><td>示例要求开始前完成提交</td><td>提醒带最晚发送时间</td></tr><tr><td>所有渠道失败怎么办</td><td>页面保留日程，记录失败供查询</td><td>预约有效性不依赖通知成功</td></tr></tbody></table><p>如果业务是医生、房间等任意时间段互斥预约，需要额外的区间冲突约束；下面的名额扣减只适用于预先划分好的场次。</p><h2 id="bao-cun-yu-yue-shi-jian-he-ban-ben" tabindex="-1">保存预约时间和版本 <a class="header-anchor" href="#bao-cun-yu-yue-shi-jian-he-ban-ben" aria-label="Permalink to &quot;保存预约时间和版本&quot;">​</a></h2><table tabindex="0"><thead><tr><th>数据</th><th>用途</th></tr></thead><tbody><tr><td><code>appointment_id</code>、<code>version</code></td><td>区分同一预约的多次改期</td></tr><tr><td><code>starts_at</code>、<code>timezone</code></td><td>保存确定的开始时刻与展示时区</td></tr><tr><td><code>status</code></td><td>confirmed、cancelled、completed 等状态</td></tr><tr><td>参与人关系与版本</td><td>决定谁有资格收到这一轮提醒</td></tr><tr><td>提醒阶段</td><td>before_24h、before_30m，分别去重</td></tr></tbody></table><p>跨时区预约不能只存“上午 9 点”。日历规则需要对应 IANA 时区，实际执行对应明确时刻。重复预约先生成具体场次，再为每场安排任务，避免改动一场后意外影响整个系列。</p><p>建议分别保存 <code>appointment_slots</code>、<code>bookings</code>、<code>booking_participants</code>、<code>reminder_plans</code> 与通知记录。预约请求键在用户范围内唯一；参与人关系使用稳定成员 ID，离开后重新加入时产生新成员轮次，避免沿用旧关系版本。</p><table tabindex="0"><thead><tr><th>接口或处理器</th><th>输入</th><th>输出与边界</th></tr></thead><tbody><tr><td>创建预约</td><td>场次、参与人、请求幂等键</td><td>预约 ID、版本和确认结果</td></tr><tr><td>改期</td><td>预约 ID、目标场次、预期版本</td><td>成功后的新版本；冲突需重新读取</td></tr><tr><td>取消</td><td>预约 ID、预期版本、请求键</td><td>幂等取消并释放原占位</td></tr><tr><td>查询日程</td><td>预约 ID</td><td>最新时间、状态和提醒记录</td></tr><tr><td>提醒展开 Worker</td><td>提醒计划 ID、预约版本、成员扫描检查点</td><td>分批创建参与人通知意图</td></tr></tbody></table><h2 id="que-rengai-qi-yu-qu-xiao-zen-yang-chu-fa" tabindex="-1">确认、改期与取消怎样触发 <a class="header-anchor" href="#que-rengai-qi-yu-qu-xiao-zen-yang-chu-fa" aria-label="Permalink to &quot;确认、改期与取消怎样触发&quot;">​</a></h2><p>确认预约时，在同一事务保存预约和提醒任务，或者保存 Outbox 事件。改期时增加版本并创建新计划；旧任务执行时发现版本不一致，记录 <code>skipped</code>。</p><p>提醒任务开始处理时，依次检查：</p><ol><li>预约仍然确认，时间和版本与本次任务一致。</li><li>参与者仍在名单中，且没有取消这一路提醒。</li><li>当前时间仍处于可接受的提醒窗口。</li><li>这一参与者、这一场次、这一提醒阶段没有完成同渠道发送。</li></ol><p>检查与外部发送之间仍有并发窗口。已经提交的短信不一定能撤回；消息中的链接应读取最新预约信息，不把旧任务参数当成当前日程。</p><p>事务与事件发布的衔接见 <a href="./../triggers/event-driven.html">Outbox 模式</a>，它解决本地提交与可靠投递之间的窗口，不保证外部通知恰好发送一次。</p><h2 id="chuang-jian-yu-yue-de-shi-wu" tabindex="-1">创建预约的事务 <a class="header-anchor" href="#chuang-jian-yu-yue-de-shi-wu" aria-label="Permalink to &quot;创建预约的事务&quot;">​</a></h2><p>以下 PostgreSQL 18 片段在已有表结构下表达名额条件，<code>:参数名</code> 由驱动绑定：</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">UPDATE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> appointment_slots</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> remaining </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> remaining </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WHERE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> id </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> :slot_id</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  AND</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> tenant_id </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> :tenant_id</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  AND</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> starts_at </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> statement_timestamp()</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  AND</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> remaining </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">RETURNING id, starts_at;</span></span></code></pre></div><p>应用事务先取得请求幂等键的处理资格，再执行名额更新。更新成功后创建预约、成员和提醒计划，一起提交；任何一步失败都回滚扣减。重复请求等待原事务结果或返回已保存的预约，不再扣一次名额。</p><p>改期时按固定顺序锁定新旧场次与预约记录，校验版本和可修改时间。占用新名额、释放旧名额、增加预约版本和保存新提醒计划一起提交。取消也只有第一次从有效状态转换时释放名额。</p><p>remaining &gt; 0 让最后一个名额的竞争发生在数据库写入时，而不是依赖两个请求各自读到的剩余数量。请求幂等键则处理另一种问题：同一个用户因响应丢失重发。库存条件不能代替请求去重，反过来也一样。</p><h2 id="ti-xing-ji-hua-ru-he-zhan-kai" tabindex="-1">提醒计划如何展开 <a class="header-anchor" href="#ti-xing-ji-hua-ru-he-zhan-kai" aria-label="Permalink to &quot;提醒计划如何展开&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>领取已到时间的 reminder_plan</span></span>
<span class="line"><span>读取预约，检查版本、状态与最晚发送时间</span></span>
<span class="line"><span>分批读取仍有效的参与人：</span></span>
<span class="line"><span>  保存场次 + 预约版本 + 成员轮次 + 提醒阶段对应的通知意图</span></span>
<span class="line"><span>  与该批展开检查点一起提交</span></span>
<span class="line"><span>展开完成后结束计划</span></span>
<span class="line"><span>渠道 Worker 再次检查预约与参与人，提交仍有效的通知</span></span></code></pre></div><p>展开期间新增的成员，不能只靠旧检查点覆盖：加入操作需要补建仍适用的通知，或使计划按新成员水位再次核对。移除成员则让已建立但尚未发送的意图在校验时退出。</p><h2 id="1000-ren-tong-yi-shi-jian-yu-yue-zen-yang-chu-li" tabindex="-1">1000 人同一时间预约怎样处理 <a class="header-anchor" href="#1000-ren-tong-yi-shi-jian-yu-yue-zen-yang-chu-li" aria-label="Permalink to &quot;1000 人同一时间预约怎样处理&quot;">​</a></h2><p>需要先区分 1000 个独立预约，还是一场有 1000 名参与者的会议。</p><table tabindex="0"><thead><tr><th>情况</th><th>拆分单位</th><th>结果记录</th></tr></thead><tbody><tr><td>1000 个独立预约</td><td>每个预约与提醒阶段</td><td>各自检查时间、状态和版本</td></tr><tr><td>一场 1000 人会议</td><td>场次提醒计划再展开参与人</td><td>每个参与者、每个渠道独立保存</td></tr></tbody></table><p>展开参与人时分批读取并保存通知任务，分页推进与任务保存原子衔接，或通过稳定业务键安全重扫。不要在一个任务里循环发完 1000 人再整体确认，进程中断后无法安全区分谁已收到。</p><p>提醒有明确的最晚发送时间。消费者按渠道限速，必要时在允许窗口内提前错峰；若额度不足以在会前完成，应提前发现容量缺口，而不是临时在整点无限提高并发。具体容量计算见<a href="./membership.html">会员批量处理</a>。</p><h2 id="zhi-xing-wan-liao-zen-me-ban" tabindex="-1">执行晚了怎么办 <a class="header-anchor" href="#zhi-xing-wan-liao-zen-me-ban" aria-label="Permalink to &quot;执行晚了怎么办&quot;">​</a></h2><table tabindex="0"><thead><tr><th>到达时刻</th><th>示例处理</th></tr></thead><tbody><tr><td>原定前 24 小时，实际前 23 小时</td><td>若仍有价值，可发送实际剩余时间</td></tr><tr><td>两档提醒同时积压到开始前 10 分钟</td><td>合并为一次仍适用的提醒</td></tr><tr><td>预约已经开始或结束</td><td>跳过过时的“即将开始”文案</td></tr><tr><td>已取消但取消事件尚未消费</td><td>发送前读取当前预约状态，阻止旧任务</td></tr></tbody></table><p>“实际剩余时间”应在发送前计算，不能直接沿用创建任务时的“还有 24 小时”。</p><h2 id="yi-ci-gai-qi-shi-bai-yu-cheng-gong-de-ji-lu-yan-bian" tabindex="-1">一次改期失败与成功的记录演变 <a class="header-anchor" href="#yi-ci-gai-qi-shi-bai-yu-cheng-gong-de-ji-lu-yan-bian" aria-label="Permalink to &quot;一次改期失败与成功的记录演变&quot;">​</a></h2><p>假设预约 B17 已占场次 S10，预约版本为 3，用户请求改到 S11：</p><table tabindex="0"><thead><tr><th>操作</th><th>应保留的记录</th><th>原因</th></tr></thead><tbody><tr><td>第一次改期，S11 已满</td><td>B17 仍关联 S10，版本仍为 3</td><td>改期失败不应丢掉原位置</td></tr><tr><td>S11 释放名额后重新提交有效请求</td><td>新占位、旧释放、B17 版本 4 和新计划一起提交</td><td>避免只改时间却漏释放或漏提醒</td></tr><tr><td>版本 3 的提醒到达</td><td>检测到当前版本 4，跳过</td><td>旧任务身份仍在，但已失效</td></tr><tr><td>为版本 4 展开 1000 人，处理到 500 人退出</td><td>前 500 人的意图与检查点已经持久化</td><td>恢复只需继续或安全重扫</td></tr><tr><td>某成员在发送前退出</td><td>其未发送意图跳过，其他成员继续</td><td>一个成员变化不应取消整场提醒</td></tr></tbody></table><p>如果取消与发送竞争，发送前的状态判断只能阻止尚未交给渠道的动作。测试时应分别观察“取消成功”与“外部消息是否已经提交”，而不是把两者当成一个原子结果。</p><h2 id="ying-yan-zheng-de-jie-guo" tabindex="-1">应验证的结果 <a class="header-anchor" href="#ying-yan-zheng-de-jie-guo" aria-label="Permalink to &quot;应验证的结果&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>应断言的结果</th></tr></thead><tbody><tr><td>最后一个名额被两个请求同时争抢</td><td>只有一个预约确认，剩余名额不小于零</td></tr><tr><td>创建请求成功但响应丢失</td><td>相同请求键返回同一预约，不再次占位</td></tr><tr><td>改期目标已满</td><td>原预约与原名额保持有效</td></tr><tr><td>展开到第 500 人后进程退出</td><td>恢复后继续或安全重扫，不重复已建意图</td></tr><tr><td>发送前移除成员或取消预约</td><td>未发送意图跳过；已提交渠道的结果可追踪</td></tr><tr><td>积压跨过预约开始时间</td><td>过时提醒停止发送并记录原因</td></tr></tbody></table><p>监控确认成功率、名额冲突、最老待展开计划、开始前提交成功比例与渠道失败。任务成功表示处理了对应提醒意图，用户是否真正看到需要独立回执。</p><h2 id="teng-xun-hui-yi-ji-cheng-fang-an-zhong-de-chong-fu-tong-zhi-ru-kou" tabindex="-1">腾讯会议集成方案中的重复通知入口 <a class="header-anchor" href="#teng-xun-hui-yi-ji-cheng-fang-an-zhong-de-chong-fu-tong-zhi-ru-kou" aria-label="Permalink to &quot;腾讯会议集成方案中的重复通知入口&quot;">​</a></h2><p>腾讯会议的<a href="https://meeting.tencent.com/support/topic/618/index.html" target="_blank" rel="noreferrer">教育场景 API 集成白皮书</a>介绍了课程、答辩和宣讲等预约场景。宣讲方案特别指出：创建会议的 API 响应与会议创建 Webhook 都可作为通知入口；如果其他流程也依赖 Webhook，建议统一由回调触发通知，避免发两次。文档还区分取消单次周期会议与取消整个系列。</p><p>对应到本文，应先统一业务事件身份，再生成通知意图。API 成功响应、回调重投和补查结果可以汇入同一入口，用“预约身份 + 版本 + 通知阶段 + 接收人”识别相同动作。仅对每个 HTTP 请求分别去重，无法识别两条不同入口携带的同一业务事实。</p><p>周期课程还需要系列 ID 与单次预约 ID：取消一节课只失效该次提醒，调整系列规则则明确影响哪些未来实例。对于 1000 名参与者，保存一次预约事实后分批展开通知，不在创建会议请求中同步发送 1000 次。这些数据模型和批量策略是本文据集成场景提出的实现建议；白皮书没有披露腾讯会议内部的提醒调度算法。</p><h2 id="teng-xun-hui-yi-hui-diao-xie-yique-ren-jie-shou-yao-fang-zai-zheng-que-de-wei-zhi" tabindex="-1">腾讯会议回调协议：确认接收要放在正确的位置 <a class="header-anchor" href="#teng-xun-hui-yi-hui-diao-xie-yique-ren-jie-shou-yao-fang-zai-zheng-que-de-wei-zhi" aria-label="Permalink to &quot;腾讯会议回调协议：确认接收要放在正确的位置&quot;">​</a></h2><p>腾讯会议的<a href="https://meeting.tencent.com/support/topic/588/" target="_blank" rel="noreferrer">企业回调服务说明</a>规定了响应时间、重试和成功响应格式。它要求的不只是 HTTP 200，还包括约定的响应正文；超时或响应不符合要求会重试。因此，一个通用 Webhook 框架即使自动返回 200，也可能无法完成该接口的成功确认。</p><p>应用可以在完成来源校验和接收记录持久化后，快速按协议确认，再异步展开参与人提醒。若在回调请求里同步通知 1000 名参与者，很容易超过供应商的等待时间，让重投与原请求同时展开同一批通知。重复事件应命中原接收结果，通知去重仍按业务身份进行。</p><p>如果接收记录没有保存成功，就不能先确认再依赖进程内队列补做；如果供应商的有限重试已经结束，则需要查询或人工核对来恢复。这一设计也适用于预约修改和取消事件，但每类事件的身份与状态转换应分别定义。</p><h2 id="can-kao-zi-liao" tabindex="-1">参考资料 <a class="header-anchor" href="#can-kao-zi-liao" aria-label="Permalink to &quot;参考资料&quot;">​</a></h2><ul><li><p>腾讯会议官方接入说明：<a href="https://meeting.tencent.com/support/topic/588/" target="_blank" rel="noreferrer">API 支持企业回调服务</a></p></li><li><p>腾讯会议官方方案：<a href="https://meeting.tencent.com/support/topic/618/index.html" target="_blank" rel="noreferrer">教育场景 API 集成白皮书</a></p></li><li><p>PostgreSQL 18：<a href="https://www.postgresql.org/docs/18/functions-datetime.html" target="_blank" rel="noreferrer">Date/Time Functions and Operators</a></p></li><li><p>AWS Prescriptive Guidance：<a href="https://docs.aws.amazon.com/prescriptive-guidance/latest/cloud-design-patterns/transactional-outbox.html" target="_blank" rel="noreferrer">Transactional outbox pattern</a></p></li><li><p>PostgreSQL 18：<a href="https://www.postgresql.org/docs/18/sql-update.html" target="_blank" rel="noreferrer">UPDATE：条件更新与 RETURNING</a></p></li></ul>`,51))])}const B=d(E,[["render",u]]);export{m as __pageData,B as default};
